DAY=86400000

def hard_stop(sid,profile):
 old=pids(profile);assert old
 for pid in old:
  try:os.kill(pid,signal.SIGKILL)
  except ProcessLookupError:pass
 wait(lambda:not pids(profile),15)
 try:call('DELETE',f'/session/{sid}')
 except Exception:pass
 return old

